class Server:
    def __init__(self):
        self.sessions = {}
    def login(self, u): self.sessions[u] = "ok"
    def whoami(self, u): return self.sessions.get(u, "logged out")
a, b = Server(), Server()
a.login("ana")
print(b.whoami("ana"))

def shard(user_id):
    return user_id % 4
for uid in [7, 12, 1001]:
    print(uid, "goes to db", shard(uid))

